knots = sorted({-b[i] / a[i] for i in range(32) if a[i] != 0})

def affine_logits(mid):
    # On a knot-free interval, every hinge is either identically zero or
    # its affine argument. Accumulate the resulting affine coefficients.
    slope = np.zeros(6)
    intercept = np.zeros(6)
    for i in range(32):
        if a[i] * mid + b[i] > 0:
            slope += C[:, i] * a[i]
            intercept += C[:, i] * b[i]
    return slope, intercept

def winner(lines, x):
    slope, intercept = lines
    values = slope * x + intercept
    # np.argmax's first-index tie convention matches argmax classification.
    return int(np.argmax(values))

def compile_rule(scale):
    # Partition the scalar axis at hinge knots, then add all pairwise
    # line-intersection points. Each resulting cell has a fixed winner.
    lo, hi = 0.0, 10.0 * scale
    cuts = sorted({lo, hi} | {k for k in knots if lo < k < hi})
    expanded = set(cuts)
    for left, right in zip(cuts[:-1], cuts[1:]):
        lines = affine_logits((left + right) / 2)
        m, c = lines
        for i in range(6):
            for j in range(i + 1, 6):
                if m[i] != m[j]:
                    root = (c[j] - c[i]) / (m[i] - m[j])
                    if left < root < right:
                        expanded.add(root)
    cuts = sorted(expanded)

    cells = []
    for left, right in zip(cuts[:-1], cuts[1:]):
        mid = (left + right) / 2
        cells.append((left, right, affine_logits(mid)))
    points = {}
    for x in cuts:
        # At a knot, either adjacent affine identity gives the same hinge
        # value; determine the tie-broken winner from the adjacent identity.
        if x == hi:
            lines = affine_logits((cuts[-2] + x) / 2)
        else:
