import json
import numpy as np
from itertools import product

b = np.asarray(W["target.b0"], dtype=float)
a = np.asarray(W["target.w0"], dtype=float)[:, 0]
C = np.asarray(W["target.w1"], dtype=float)
knots = sorted({-b[i] / a[i] for i in range(32) if a[i] != 0})

def affine_logits(mid):
    slope = np.zeros(6)
    intercept = np.zeros(6)
    for i in range(32):
        if a[i] * mid + b[i] > 0:
            slope += C[:, i] * a[i]
            intercept += C[:, i] * b[i]
    return slope, intercept

def winner(lines, x, head):
    slope, intercept = lines
    start = 3 * head
    return int(np.argmax(slope[start:start+3] * x + intercept[start:start+3]))

def compile_rule(scale):
    lo, hi = 0.0, 10.0 * scale
    cuts = sorted({lo, hi} | {k for k in knots if lo < k < hi})
    expanded = set(cuts)
    for left, right in zip(cuts[:-1], cuts[1:]):
        m, c = affine_logits((left + right) / 2)
        for h in range(2):
            start = 3 * h
            for i in range(start, start + 3):
                for j in range(i + 1, start + 3):
                    if m[i] != m[j]:
                        root = (c[j] - c[i]) / (m[i] - m[j])
                        if left < root < right:
                            expanded.add(root)
    cuts = sorted(expanded)
    cells = [(left, right, affine_logits((left + right) / 2))
             for left, right in zip(cuts[:-1], cuts[1:])]
    points = {}
    for idx, x in enumerate(cuts):
        if idx + 1 < len(cuts):
            mid = (x + cuts[idx + 1]) / 2
        else:
            mid = (cuts[idx - 1] + x) / 2
        lines = affine_logits(mid)
        points[x] = [winner(lines, x, h) for h in range(2)]
    return cells, points

rules = {scale: compile_rule(scale) for scale in (1.0, 0.67)}

def predict(total, scale, head):
    x = scale * total
    cells, points = rules[scale]
    if x in points:
        return points[x][head]
    _, _, lines = next(cell for cell in cells if cell[0] < x < cell[1])
    return winner(lines, x, head)

